def add_old(slug):
    p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "rewrites", slug.replace("/", "_") + ".html")
    s = open(p, encoding="utf-8").read()
    s = re.sub(r'\n?<h2 id="sources">Sources and further reading</h2>\n<ul class="bd-sources">.*?</ul>\n', "", s, flags=re.S)
    li = "\n".join('<li><a href="%s" rel="noopener" target="_blank">%s</a></li>' % (html.escape(S[k][1], quote=True), html.escape(S[k][0])) for k in OLD[slug])
    s = s.rstrip("\n") + '\n\n<h2 id="sources">Sources and further reading</h2>\n<ul class="bd-sources">\n%s\n</ul>\n' % li
    open(p, "w", encoding="utf-8").write(s)

